    // -----------------------------------------------------------------
    // WA4 — alternating row stripes via `data-row:even` / `:odd` state
    // blocks on the `sheet/data-row` sub-part.
    // -----------------------------------------------------------------

    /// Helper: build a Grid StyleDef whose `sheet/data-row` sub-part
    /// declares `state even` and `state odd` blocks with the given props.
    fn style_with_data_row_states(
        component: &str,
        even: &[(&str, &str)],
        odd: &[(&str, &str)],
    ) -> StyleDef {
        let mut states: Vec<StateStyle> = Vec::new();
        if !even.is_empty() {
            states.push(StateStyle {
                state: "even".to_string(),
                transitions: vec![],
                props: even
                    .iter()
                    .map(|(k, v)| StyleProp {
                        name: k.to_string(),
                        value: v.to_string(),
                    })
                    .collect(),
            });
        }
        if !odd.is_empty() {
            states.push(StateStyle {
                state: "odd".to_string(),
                transitions: vec![],
                props: odd
                    .iter()
                    .map(|(k, v)| StyleProp {
                        name: k.to_string(),
                        value: v.to_string(),
                    })
                    .collect(),
            });
        }
        StyleDef {
            component_name: component.to_string(),
            parts: vec![PartStyle {
                name: "sheet/data-row".to_string(),
                base: Vec::new(),
                transitions: vec![],
                states,
            }],
        }
    }

    fn grid_with_stripes_layout(component: &str) -> LayoutDef {
        LayoutDef {
            component_name: component.to_string(),
            root: LayoutNode {
                tag: "Grid".to_string(),
                part_name: Some("sheet".to_string()),
                props: vec![
                    slot_ref_prop("headers", "col-labels"),
                    slot_ref_prop("rows", "data-rows"),
                ],
                children: Vec::new(),
            },
        }
    }

    fn grid_with_stripes_component(name: &str) -> MosmodelComponent {
        component(
            name,
            vec![
                slot(
                    "col-labels",
                    SlotType::List(Box::new(ListInnerType::Text)),
                    true,
                ),
                slot(
                    "data-rows",
                    SlotType::List(Box::new(ListInnerType::Text)),
                    true,
                ),
            ],
            vec![],
        )
    }

    // -----------------------------------------------------------------
    // WA5 — sticky header + scroll container
    // -----------------------------------------------------------------

    fn grid_sticky_layout(
        component: &str,
        sticky: bool,
        total_height: Option<f64>,
        total_height_slot: Option<&str>,
    ) -> LayoutDef {
        let mut props = vec![
            slot_ref_prop("headers", "col-labels"),
            slot_ref_prop("rows", "data-rows"),
        ];
        if sticky {
            props.push(LayoutProp {
                name: "sticky-header".to_string(),
                value: LayoutPropValue::Keyword("true".to_string()),
            });
        }
        if let Some(n) = total_height {
            props.push(LayoutProp {
                name: "total-height".to_string(),
                value: LayoutPropValue::Number(n),
            });
        }
        if let Some(slot_name) = total_height_slot {
            props.push(LayoutProp {
                name: "total-height".to_string(),
                value: LayoutPropValue::SlotRef(slot_name.to_string()),
            });
        }
        LayoutDef {
            component_name: component.to_string(),
            root: LayoutNode {
                tag: "Grid".to_string(),
                part_name: None,
                props,
                children: Vec::new(),
            },
        }
    }

