    #[test]
    fn strip_on_prefix_handles_various_inputs() {
        assert_eq!(strip_on_prefix("onClick"), "Click");
        assert_eq!(strip_on_prefix("onNavigate"), "Navigate");
        assert_eq!(strip_on_prefix("On"), "");
        assert_eq!(strip_on_prefix("foo"), "foo"); // no prefix to strip
        assert_eq!(strip_on_prefix("o"), "o"); // too short
        assert_eq!(strip_on_prefix(""), "");
    }

    #[test]
    fn to_camel_case_first_lower_truth_table() {
        assert_eq!(to_camel_case_first_lower("avatar-url"), "avatarUrl");
        assert_eq!(to_camel_case_first_lower("display-name"), "displayName");
        assert_eq!(to_camel_case_first_lower("Navigate"), "navigate");
        assert_eq!(to_camel_case_first_lower("formula"), "formula");
        assert_eq!(to_camel_case_first_lower("start-row"), "startRow");
    }

    #[test]
    fn is_safe_js_identifier_accepts_and_rejects_correctly() {
        assert!(is_safe_js_identifier("foo"));
        assert!(is_safe_js_identifier("_bar"));
        assert!(is_safe_js_identifier("Baz9"));
        assert!(!is_safe_js_identifier(""));
        assert!(!is_safe_js_identifier("9foo"));
        assert!(!is_safe_js_identifier("foo-bar"));
        assert!(!is_safe_js_identifier("foo bar"));
        assert!(!is_safe_js_identifier("\"}; alert(1);//"));
    }

